using Clock = std::chrono::steady_clock;
constexpr std::int32_t kHeadDim = 256;
constexpr std::int32_t kQueryHeads = 24;
constexpr std::int32_t kKvHeads = 4;
constexpr std::int32_t kQuantGroup = 64;
constexpr std::int32_t kScaleRows = kHeadDim / kQuantGroup;
constexpr float kAttentionScale = 0.0625F;
constexpr double kRelativeL2Tolerance = 3.15e-3;
struct Options { int fast_device=0; int slow_device=1; std::int32_t tokens=4; std::int32_t window=65536; int warmup=8; int repeat=30; double fast_fraction=0.566; };
std::uint64_t parse_u64(std::string_view text,const char*label){std::string value(text);char*end=nullptr;const unsigned long long parsed=std::strtoull(value.c_str(),&end,10);if(end==value.c_str()||*end!='\0')throw std::invalid_argument(std::string("invalid ")+label+": "+value);return parsed;}
int parse_int(std::string_view text,const char*label,int minimum,int maximum){const auto value=parse_u64(text,label);if(value<static_cast<std::uint64_t>(minimum)||value>static_cast<std::uint64_t>(maximum))throw std::invalid_argument(std::string(label)+" is outside the supported range");return static_cast<int>(value);}
double parse_double(std::string_view text,const char*label){std::string value(text);char*end=nullptr;const double parsed=std::strtod(value.c_str(),&end);if(end==value.c_str()||*end!='\0'||!std::isfinite(parsed))throw std::invalid_argument(std::string("invalid ")+label+": "+value);return parsed;}
[[noreturn]] void usage(const char*argv0,const char*error=nullptr){if(error)std::fprintf(stderr,"error: %s\n\n",error);std::fprintf(stderr,"Usage: %s [options]\n  --fast-device N\n  --slow-device N\n  --tokens N\n  --window N\n  --fast-fraction F\n  --warmup N\n  --repeat N\n",argv0);std::exit(error?2:0);}
Options parse_options(int argc,char**argv){Options out;for(int index=1;index<argc;++index){const std::string_view arg(argv[index]);const auto take=[&](const char*label)->std::string_view{if(++index>=argc)usage(argv[0],(std::string("missing ")+label).c_str());return argv[index];};if(arg=="--fast-device")out.fast_device=parse_int(take("device"),"device",0,63);else if(arg=="--slow-device")out.slow_device=parse_int(take("device"),"device",0,63);else if(arg=="--tokens")out.tokens=parse_int(take("tokens"),"tokens",1,6);else if(arg=="--window")out.window=parse_int(take("window"),"window",1,262144);else if(arg=="--fast-fraction")out.fast_fraction=parse_double(take("fraction"),"fraction");else if(arg=="--warmup")out.warmup=parse_int(take("warmup"),"warmup",0,10000);else if(arg=="--repeat")out.repeat=parse_int(take("repeat"),"repeat",1,10000);else if(arg=="--help"||arg=="-h")usage(argv[0]);else usage(argv[0],(std::string("unknown argument: ")+std::string(arg)).c_str());}if(out.fast_device==out.slow_device)usage(argv[0],"devices must differ");if(out.window<out.tokens)usage(argv[0],"window must be >= tokens");if(!(out.fast_fraction>0.0&&out.fast_fraction<1.0))usage(argv[0],"fast fraction must be in (0,1)");return out;}
std::size_t checked_product(std::initializer_list<std::uint64_t> dimensions){std::uint64_t product=1;for(const auto dimension:dimensions){if(dimension==0||product>std::numeric_limits<std::uint64_t>::max()/dimension)throw std::overflow_error("tensor size overflow");product*=dimension;}if(product>std::numeric_limits<std::size_t>::max())throw std::overflow_error("tensor size exceeds size_t");return static_cast<std::size_t>(product);}
float bf16_to_float(std::uint16_t value){std::uint32_t bits=static_cast<std::uint32_t>(value)<<16;float output=0;std::memcpy(&output,&bits,sizeof(output));return output;}
struct Comparison{std::size_t bit_mismatches=0;double max_abs=0,mean_abs=0,relative_l2=0,cosine=0;};
Comparison compare_bf16(const std::vector<std::uint16_t>&a,const std::vector<std::uint16_t>&b){if(a.size()!=b.size())throw std::invalid_argument("compare size mismatch");Comparison r;double sa=0,sd=0,saa=0,sbb=0,dot=0;for(std::size_t i=0;i<a.size();++i){r.bit_mismatches+=a[i]!=b[i];const double x=bf16_to_float(a[i]),y=bf16_to_float(b[i]),d=y-x,ad=std::abs(d);r.max_abs=std::max(r.max_abs,ad);sa+=ad;sd+=d*d;saa+=x*x;sbb+=y*y;dot+=x*y;}r.mean_abs=a.empty()?0:sa/a.size();r.relative_l2=saa>0?std::sqrt(sd/saa):0;r.cosine=saa>0&&sbb>0?dot/std::sqrt(saa*sbb):1;return r;}
double median(std::vector<double>v){std::sort(v.begin(),v.end());return v[v.size()/2];}
class DeviceFixture{
public:
 DeviceFixture(int device_id,std::int32_t tokens,std::int32_t window):device_id_(device_id),device_(device_id),tokens_(tokens),window_(window),pages_((window+kPagedKVPageSize-1)/kPagedKVPageSize),splits_(ops::detail::gqa_attention_split_capacity(kQueryHeads,tokens,DType::I8,{static_cast<std::uint32_t>(window),static_cast<std::uint32_t>(window)})){activate();const std::size_t code=checked_product({static_cast<std::uint64_t>(kHeadDim),static_cast<std::uint64_t>(kPagedKVPageSize),static_cast<std::uint64_t>(kKvHeads),static_cast<std::uint64_t>(pages_)});const std::size_t scales=checked_product({static_cast<std::uint64_t>(kScaleRows),static_cast<std::uint64_t>(kPagedKVPageSize),static_cast<std::uint64_t>(kKvHeads),static_cast<std::uint64_t>(pages_)});const std::size_t qn=checked_product({static_cast<std::uint64_t>(kHeadDim),static_cast<std::uint64_t>(kQueryHeads),static_cast<std::uint64_t>(tokens_)});const std::size_t pn=qn*static_cast<std::size_t>(splits_);const std::size_t ps=checked_product({static_cast<std::uint64_t>(kQueryHeads),static_cast<std::uint64_t>(tokens_),static_cast<std::uint64_t>(splits_)});const std::size_t ss=static_cast<std::size_t>(kQueryHeads)*tokens_;state_acc_bytes_=qn*sizeof(float);state_m_bytes_=ss*sizeof(float);state_bytes_=state_acc_bytes_+2*state_m_bytes_;k_cache_=DeviceBuffer(code);v_cache_=DeviceBuffer(code);k_scale_=DeviceBuffer(scales*2);v_scale_=DeviceBuffer(scales*2);block_table_=DeviceBuffer(static_cast<std::size_t>(pages_)*4);q_=DeviceBuffer(qn*2);positions_=DeviceBuffer(static_cast<std::size_t>(tokens_)*4);partial_acc_=DeviceBuffer(pn*2);partial_m_=DeviceBuffer(ps*4);partial_l_=DeviceBuffer(ps*4);state_packet_=DeviceBuffer(state_bytes_);remote_state_packet_=DeviceBuffer(state_bytes_);output_=DeviceBuffer(qn*2);const std::size_t wb=ops::gqa_attention_workspace_capacity_bytes(kQueryHeads,DType::I8,envelope(),1,tokens_,tokens_);workspace_=std::make_unique<WorkspaceArena>(std::max<std::size_t>(wb,256));initialise();CUDA_CHECK(cudaEventCreateWithFlags(&remote_ready_,cudaEventDisableTiming));}
 ~DeviceFixture(){activate_noexcept();if(remote_ready_)cudaEventDestroy(remote_ready_);}
 DeviceFixture(const DeviceFixture&)=delete;DeviceFixture&operator=(const DeviceFixture&)=delete;
 void activate()const{CUDA_CHECK(cudaSetDevice(device_id_));}void activate_noexcept()const noexcept{cudaSetDevice(device_id_);}void synchronize()const{device_.synchronize();}int splits()const noexcept{return splits_;}std::size_t state_bytes()const noexcept{return state_bytes_;}
 void launch_full(){activate();workspace_->reset();Tensor out=output_tensor();ops::gqa_attention_cached(q_tensor(),positions_tensor(),kAttentionScale,cache_view(),envelope(),*workspace_,out,device_.stream);workspace_->reset();}
 void launch_range(std::int32_t begin,std::int32_t count){activate();Tensor q=q_tensor();Tensor positions=positions_tensor();auto cache=cache_view();Tensor partial_acc=partial_acc_tensor();Tensor partial_m=partial_m_tensor();Tensor partial_l=partial_l_tensor();ops::detail::gqa_attention_cached_small_t_partial_range_launch(q,positions,kAttentionScale,cache,envelope(),begin,count,partial_acc,partial_m,partial_l,device_.stream);Tensor state_acc=state_acc_tensor(state_packet_);Tensor state_m=state_m_tensor(state_packet_);Tensor state_l=state_l_tensor(state_packet_);ops::detail::gqa_attention_small_t_reduce_range_state_launch(kQueryHeads,tokens_,splits_,begin,count,partial_acc,partial_m,partial_l,state_acc,state_m,state_l,device_.stream);}
 void download_state(PinnedHostBuffer&host){activate();if(host.size()!=state_bytes_)throw std::invalid_argument("state host size mismatch");CUDA_CHECK(cudaMemcpyAsync(host.data(),state_packet_.p,state_bytes_,cudaMemcpyDeviceToHost,device_.stream));}
 void upload_remote_state(PinnedHostBuffer&host){activate();if(host.size()!=state_bytes_)throw std::invalid_argument("state host size mismatch");CUDA_CHECK(cudaMemcpyAsync(remote_state_packet_.p,host.data(),state_bytes_,cudaMemcpyHostToDevice,device_.load_stream));CUDA_CHECK(cudaEventRecord(remote_ready_,device_.load_stream));CUDA_CHECK(cudaStreamWaitEvent(device_.stream,remote_ready_,0));}
 void merge_remote_state(){activate();Tensor out=output_tensor();ops::detail::gqa_attention_small_t_merge_two_states_launch(kQueryHeads,tokens_,state_acc_tensor(state_packet_),state_m_tensor(state_packet_),state_l_tensor(state_packet_),state_acc_tensor(remote_state_packet_),state_m_tensor(remote_state_packet_),state_l_tensor(remote_state_packet_),out,device_.stream);}
 std::vector<std::uint16_t> copy_output(){activate();std::vector<std::uint16_t>host(output_.bytes/2);output_.copy_to_host(host.data(),output_.bytes);return host;}
private:
 void initialise(){activate();k_cache_.fill(0x11);v_cache_.fill(0x2d);std::vector<std::uint16_t>scales(k_scale_.bytes/2,0x3c00U);k_scale_.copy_from_host(scales.data(),k_scale_.bytes);v_scale_.copy_from_host(scales.data(),v_scale_.bytes);std::vector<std::int32_t>table(static_cast<std::size_t>(pages_));std::iota(table.begin(),table.end(),0);block_table_.copy_from_host(table.data(),block_table_.bytes);std::vector<std::uint16_t>qh(q_.bytes/2);for(std::size_t i=0;i<qh.size();++i){const std::uint32_t mixed=static_cast<std::uint32_t>(i)*1664525U+1013904223U+17U;const float value=(static_cast<float>(mixed&1023U)/1023.0F-0.5F)*0.5F;qh[i]=ninfer::bench::f32_to_bf16(value);}q_.copy_from_host(qh.data(),q_.bytes);std::vector<std::int32_t>pos(static_cast<std::size_t>(tokens_));const std::int32_t begin=window_-tokens_;for(std::int32_t t=0;t<tokens_;++t)pos[t]=begin+t;positions_.copy_from_host(pos.data(),positions_.bytes);partial_acc_.fill();partial_m_.fill();partial_l_.fill();state_packet_.fill();remote_state_packet_.fill();output_.fill();device_.synchronize();}
 ops::GqaExecutionEnvelope envelope()const{return{static_cast<std::uint32_t>(window_),static_cast<std::uint32_t>(window_)};}
 Tensor q_tensor(){return Tensor(q_.p,DType::BF16,{kHeadDim,kQueryHeads,tokens_});}Tensor positions_tensor(){return Tensor(positions_.p,DType::I32,{tokens_});}Tensor partial_acc_tensor(){return Tensor(partial_acc_.p,DType::BF16,{kHeadDim,kQueryHeads,tokens_,splits_});}Tensor partial_m_tensor(){return Tensor(partial_m_.p,DType::FP32,{kQueryHeads,tokens_,splits_});}Tensor partial_l_tensor(){return Tensor(partial_l_.p,DType::FP32,{kQueryHeads,tokens_,splits_});}Tensor output_tensor(){return Tensor(output_.p,DType::BF16,{kHeadDim,kQueryHeads,tokens_});}Tensor state_acc_tensor(DeviceBuffer&p){return Tensor(p.p,DType::FP32,{kHeadDim,kQueryHeads,tokens_});}Tensor state_m_tensor(DeviceBuffer&p){return Tensor(static_cast<std::uint8_t*>(p.p)+state_acc_bytes_,DType::FP32,{kQueryHeads,tokens_});}Tensor state_l_tensor(DeviceBuffer&p){return Tensor(static_cast<std::uint8_t*>(p.p)+state_acc_bytes_+state_m_bytes_,DType::FP32,{kQueryHeads,tokens_});}
 PagedKVLayerView cache_view(){return{.k_pages=Tensor(k_cache_.p,DType::I8,{kHeadDim,kPagedKVPageSize,kKvHeads,pages_}),.v_pages=Tensor(v_cache_.p,DType::I8,{kHeadDim,kPagedKVPageSize,kKvHeads,pages_}),.k_scale_pages=Tensor(k_scale_.p,DType::FP16,{kScaleRows,kPagedKVPageSize,kKvHeads,pages_}),.v_scale_pages=Tensor(v_scale_.p,DType::FP16,{kScaleRows,kPagedKVPageSize,kKvHeads,pages_}),.block_table=Tensor(block_table_.p,DType::I32,{pages_}),.head_dim=kHeadDim,.num_kv_heads=kKvHeads,.dtype=DType::I8,.quant_group=kQuantGroup};}
 int device_id_;DeviceContext device_;std::int32_t tokens_,window_,pages_,splits_;std::size_t state_acc_bytes_=0,state_m_bytes_=0,state_bytes_=0;DeviceBuffer k_cache_,v_cache_,k_scale_,v_scale_,block_table_,q_,positions_,partial_acc_,partial_m_,partial_l_,state_packet_,remote_state_packet_,output_;std::unique_ptr<WorkspaceArena>workspace_;cudaEvent_t remote_ready_=nullptr;
};
double time_full(DeviceFixture&fast){const auto start=Clock::now();fast.launch_full();fast.synchronize();return std::chrono::duration<double,std::micro>(Clock::now()-start).count();}
double time_dual(DeviceFixture&fast,DeviceFixture&slow,PinnedHostBuffer&host,std::int32_t fs){const auto start=Clock::now();fast.launch_range(0,fs);slow.launch_range(fs,fast.splits()-fs);slow.download_state(host);slow.synchronize();fast.upload_remote_state(host);fast.merge_remote_state();fast.synchronize();return std::chrono::duration<double,std::micro>(Clock::now()-start).count();}
}
int main(int argc,char**argv){try{const Options o=parse_options(argc,argv);DeviceFixture fast(o.fast_device,o.tokens,o.window);DeviceFixture slow(o.slow_device,o.tokens,o.window);if(fast.splits()!=slow.splits()||fast.splits()<2)throw std::runtime_error("split capacity mismatch");const std::int32_t fs=std::clamp(static_cast<std::int32_t>(std::llround(fast.splits()*o.fast_fraction)),1,fast.splits()-1);PinnedHostBuffer host(fast.state_bytes());fast.launch_full();fast.synchronize();const auto ref=fast.copy_output();(void)time_dual(fast,slow,host,fs);const auto cand=fast.copy_output();const Comparison cmp=compare_bf16(ref,cand);if(!std::isfinite(cmp.relative_l2)||cmp.relative_l2>kRelativeL2Tolerance)throw std::runtime_error("context-parallel output exceeds public GQA relative-L2 tolerance");for(int i=0;i<o.warmup;++i){if(i&1){(void)time_dual(fast,slow,host,fs);(void)time_full(fast);}else{(void)time_full(fast);(void)time_dual(fast,slow,host,fs);}}std::vector<double>full,dual;for(int i=0;i<o.repeat;++i){if(i&1){dual.push_back(time_dual(fast,slow,host,fs));full.push_back(time_full(fast));}else{full.push_back(time_full(fast));dual.push_back(time_dual(fast,slow,host,fs));}}const double fm=median(full),dm=median(dual);std::printf("gqa_context_parallel T=%d window=%d total_splits=%d fast_splits=%d slow_splits=%d fast_fraction=%.6f full_median_us=%.3f dual_median_us=%.3f speedup=%.6f state_bytes=%zu bit_mismatches=%zu max_abs=%.9g mean_abs=%.9g relative_l2=%.9g cosine=%.12g\n",o.tokens,o.window,fast.splits(),fs,fast.splits()-fs,o.fast_fraction,fm,dm,fm/dm,fast.state_bytes(),cmp.bit_mismatches,cmp.max_abs,cmp.mean_abs,cmp.relative_l2,cmp.cosine);return 0;}catch(const std::exception&e){std::fprintf(stderr,"error: %s\n",e.what());return 1;}}
